tasks.instructions:
ממש את הפעולה "מסלול-עולה" בעבור עץ מספרים tr.
כותרת הפעולה:
public static boolean upPath(BinNode<Integer> tr)

tasks.solution:
public static boolean upPath(BinNode<Integer> tr) {
    if (!tr.hasLeft() && !tr.hasRight()) {
        return true;
    }
    if (tr.hasLeft() && tr.getLeft().getValue() > tr.getValue() && upPath(tr.getLeft())) {
        return true;
    }
    return tr.hasRight() && tr.getRight().getValue() > tr.getValue() && upPath(tr.getRight());
}

givenCode.code:
public static String check(Object got, Object expected) {
    String g = String.valueOf(got);
    String e = String.valueOf(expected);
    if (g.equals(e)) {
        return "נכון";
    }
    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

exercise.mainCode:
BinNode<Integer> tr1 = new BinNode<Integer>(
    new BinNode<Integer>(new BinNode<Integer>(null, 3, new BinNode<Integer>(new BinNode<Integer>(5), 8, null)), 6, new BinNode<Integer>(4)),
    1,
    new BinNode<Integer>(new BinNode<Integer>(new BinNode<Integer>(19), 17, new BinNode<Integer>(12)), 2, new BinNode<Integer>(null, 11, new BinNode<Integer>(10))));
BinNode<Integer> tr2 = new BinNode<Integer>(
    new BinNode<Integer>(new BinNode<Integer>(null, 3, new BinNode<Integer>(new BinNode<Integer>(5), 8, null)), 6, new BinNode<Integer>(4)),
    1,
    new BinNode<Integer>(new BinNode<Integer>(new BinNode<Integer>(9), 14, new BinNode<Integer>(11)), 7, new BinNode<Integer>(null, 2, new BinNode<Integer>(10))));
System.out.println("סעיף א, בדיקה 1 (tr1): " + check(upPath(tr1), true));
System.out.println("סעיף א, בדיקה 2 (tr2): " + check(upPath(tr2), false));
System.out.println("סעיף א, בדיקה 3 (צומת אחד): " + check(upPath(new BinNode<Integer>(7)), true));
BinNode<Integer> t4 = new BinNode<Integer>(new BinNode<Integer>(9), 5, new BinNode<Integer>(2));
System.out.println("סעיף א, בדיקה 4 (עולה רק שמאלה): " + check(upPath(t4), true));
BinNode<Integer> t5 = new BinNode<Integer>(null, 1, new BinNode<Integer>(new BinNode<Integer>(2), 3, null));
System.out.println("סעיף א, בדיקה 5 (עולה, אבל לא עד עלה): " + check(upPath(t5), false));

